 10	public class DefaultSimulationDisplayStrategy implements SimulationDisplayStrategy
 11	{
 12	    private static final Color EMPTY_COLOR = Color.white;
 13	    private static final Color UNKNOWN_COLOR = Color.gray;
 14	    private static final Color INFECTED_COLOR = Color.green;
 15	    private static final Color STORM_COLOR = Color.blue;
 16	
 17	    private static final String DAYTIME_TEXT = "daytime";
 18	    private static final String NIGHT_TEXT = "night";
 19	
 20	    private final Map<Class<?>, Color> colors;
 21	    private final FieldStats stats;
 22	
 23	    public DefaultSimulationDisplayStrategy()
 24	    {
 25	        colors = new HashMap<>();
 26	        stats = new FieldStats();
 27	        registerDefaultColors();
 28	    }
 29	
 30	    @Override
 31	    public void setColor(Class<?> animalClass, Color color)
 32	    {
 33	        colors.put(animalClass, color);
 34	    }
 35	
 36	    @Override
 37	    public String formatInfoText(SimulationDisplayContext context)
 38	    {
 39	        return "It is: " + (context.isTimeOfDay() ? DAYTIME_TEXT : NIGHT_TEXT)
 40	            + "        Oxygen Level: " + (int)(context.getOxygenLevel() * 100) + "%"
 41	            + "        Storm: " + (context.getWeather().getStormStart() ? "exists" : "subsides");
 42	    }
 43	
 44	    @Override
 45	    public String formatPopulationText(Field field)
 46	    {
 47	        return stats.getPopulationDetails(field);
 48	    }
