 50	    @Override
 51	    public void render(SimulationDisplayContext context, GridCanvas canvas)
 52	    {
 53	        Field field = context.getField();
 54	        stats.reset();
 55	        canvas.preparePaint();
 56	
 57	        Set<Location> stormLocations = stormLocations(context);
 58	        for(int row = 0; row < field.getDepth(); row++) {
 59	            for(int col = 0; col < field.getWidth(); col++) {
 60	                Location location = new Location(row, col);
 61	                Object creature = field.getObjectAt(row, col);
 62	                Color color = EMPTY_COLOR;
 63	
 64	                if(creature != null) {
 65	                    stats.incrementCount(creature.getClass());
 66	                    color = colorFor(creature);
 67	                }
 68	
 69	                if(stormLocations.contains(location)) {
 70	                    color = STORM_COLOR;
 71	                }
 72	
 73	                canvas.drawMark(col, row, color);
 74	            }
 75	        }
 76	
 77	        stats.countFinished();
 78	        canvas.repaint();
 79	    }
