 87	    private void registerDefaultColors()
 88	    {
 89	        setColor(Cod.class, Color.ORANGE);
 90	        setColor(Salmon.class, Color.YELLOW);
 91	        setColor(Seaweed.class, Color.RED);
 92	        setColor(Shark.class, Color.BLACK);
 93	        setColor(Whale.class, Color.PINK);
 94	        setColor(Weather.class, STORM_COLOR);
 95	    }
 96	
 97	    private Color colorFor(Object creature)
 98	    {
 99	        if(creature instanceof Animal) {
100	            Animal animal = (Animal)creature;
101	            if(animal.getIsInfected() && !animal.getIsImmuned()) {
102	                return INFECTED_COLOR;
103	            }
104	        }
105	
106	        Color color = colors.get(creature.getClass());
107	        if(color == null) {
108	            return UNKNOWN_COLOR;
109	        }
110	        return color;
111	    }
