113	    private Set<Location> stormLocations(SimulationDisplayContext context)
114	    {
115	        Set<Location> locations = new HashSet<>();
116	        Weather weather = context.getWeather();
117	        if(weather.getStormStart() && weather.getRandomLocation() != null) {
118	            locations.addAll(context.getField().adjacentLocationsIncludingSelf(weather.getRandomLocation(), weather.getStormScope()));
119	        }
120	        return locations;
121	    }
